let task=0,row=0,method='',yaw=.56,pitch=.37,zoom=1,views=[],frame=0;
const $=id=>document.getElementById(id);
function buttons(id,names,active,change){let el=$(id);el.replaceChildren();names.forEach((name,i)=>{let b=document.createElement('button');b.textContent=name;b.className='tab-button'+(i===active?' active':'');b.setAttribute('aria-pressed',i===active);b.onclick=()=>change(i);el.append(b)})}
function bytes(s,T){return new T(Uint8Array.from(atob(s),c=>c.charCodeAt(0)).buffer)}
function mount(el,name,data,color,inset=false){let label=document.createElement(inset?'small':'strong');label.textContent=name;el.append(label);if(typeof data==='string'){let im=new Image;im.alt=name;im.src=data;el.append(im);return}
let cv=document.createElement('canvas');el.append(cv);let v=bytes(data[0],Int16Array),f=bytes(data[1],Uint16Array),rgb=bytes(data[2],Uint8Array);views.push({cv,v,f,rgb,color});let last;cv.onpointerdown=e=>{cv.setPointerCapture(e.pointerId);last=[e.clientX,e.clientY]};cv.onpointermove=e=>{if(!last)return;yaw+=(e.clientX-last[0])*.011;pitch=Math.max(-1.53,Math.min(1.53,pitch+(e.clientY-last[1])*.009));last=[e.clientX,e.clientY];draw()};cv.onlostpointercapture=()=>last=null;cv.onwheel=e=>{e.preventDefault();zoom=Math.min(3.6,Math.max(.45,zoom*Math.exp(-.0015*e.deltaY)));draw()};if(data[3]){let box=document.createElement('div');box.className='inset';el.append(box);mount(box,'Points',data[3],color,true)}}
function draw(){cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{for(let {cv,v,f,rgb,color} of views){let w=cv.clientWidth,h=cv.clientHeight,d=Math.min(1.6,devicePixelRatio);cv.width=Math.round(w*d);cv.height=Math.round(h*d);let ctx=cv.getContext('2d');ctx.scale(d,d);let n=v.length/3,x=new Float32Array(n),y=new Float32Array(n),depth=new Float32Array(n),scale=Math.min(w,h)*.40*zoom/30000,cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch);
for(let i=0;i<n;i++){let a=v[i*3],b=v[i*3+1],c=v[i*3+2],back=a*sy+b*cy;x[i]=w/2+scale*(a*cy-b*sy);y[i]=h*.53-scale*(back*sp+c*cp);depth[i]=back*cp-c*sp}
let tint=(k)=>'rgb('+color.map(c=>Math.min(255,c*k)|0).join(',')+')';
if(f.length){let ids=Array.from({length:f.length/3},(_,i)=>i*3),z=i=>depth[f[i]]+depth[f[i+1]]+depth[f[i+2]];ids.sort((a,b)=>z(b)-z(a));for(let i of ids){let a=f[i],b=f[i+1],c=f[i+2],ax=v[3*b]-v[3*a],ay=v[3*b+1]-v[3*a+1],az=v[3*b+2]-v[3*a+2],bx=v[3*c]-v[3*a],by=v[3*c+1]-v[3*a+1],bz=v[3*c+2]-v[3*a+2],nx=ay*bz-az*by,ny=az*bx-ax*bz,nz=ax*by-ay*bx;ctx.fillStyle=tint(.68+.43*Math.abs((-.45*nx-.28*ny+.84*nz)/(Math.hypot(nx,ny,nz)||1)));ctx.beginPath();ctx.moveTo(x[a],y[a]);ctx.lineTo(x[b],y[b]);ctx.lineTo(x[c],y[c]);ctx.closePath();ctx.fill();ctx.strokeStyle=f.length<1200?'#1c394638':ctx.fillStyle;ctx.lineWidth=.55;ctx.stroke()}}
else{let ids=Array.from({length:n},(_,i)=>i).sort((a,b)=>depth[b]-depth[a]),size=Math.max(1.15,Math.min(w,h)*zoom*(n<2000?.011:.007)),palette=Array.from({length:64},(_,i)=>tint(.58+i*.009));for(let i of ids){ctx.fillStyle=rgb.length?'rgb('+rgb[3*i]+','+rgb[3*i+1]+','+rgb[3*i+2]+')':palette[Math.max(0,Math.min(63,32-(depth[i]/1100|0)))];ctx.fillRect(x[i]-size/2,y[i]-size/2,size,size)}}}})}
function selectTask(i){task=i;row=0;method='';resetView();render()}
function resetView(){yaw=.56;pitch=.37;zoom=1;draw()}
function render(){let data=sets[task][row],base=Object.keys(data).filter(k=>!['GT','Input','Any2Building','Rough prior','Partial points'].includes(k));if(!base.includes(method))method=base[0];$('heading').textContent=titles[task];buttons('modules',['BuildingPCC','BuildingWorld-Image'],+!!task,i=>selectTask(i));buttons('tasks',task?['Point clouds','Image + points','Single image','Image + prior']:[],task-1,i=>selectTask(i+1));buttons('cases',sets[task].map((_,i)=>'Building '+(i+1)),row,i=>{row=i;render()});buttons('methods',base,base.indexOf(method),i=>{method=base[i];render()});views=[];for(let id of ['refs','ours','other'])$(id).replaceChildren();for(let k of ['Input','Partial points','Rough prior','GT'])if(data[k]){let box=document.createElement('div');box.className='card';$('refs').append(box);mount(box,k,data[k],k==='GT'?[231,161,78]:[142,161,170])}mount($('ours'),'Any2Building',data.Any2Building,[69,163,198]);mount($('other'),method,data[method],[[91,173,130],[147,127,185],[205,123,109]][base.indexOf(method)]);draw()}
$('reset').onclick=resetView;window.addEventListener('resize',draw);render();

